    if(allianceFocusPlayer_>=0){auto it=std::find(visible.begin(),visible.end(),unsigned(allianceFocusPlayer_));if(it!=visible.end()){auto field=context(unsigned(it-visible.begin()))+(allianceFocusResource_?"/LumberBackdrop":"/GoldBackdrop");auto r=screen.bounds(field);float scale=std::min(renderer_.width()/.8f,renderer_.height()/.6f),left=(renderer_.width()-.8f*scale)/2,top=(renderer_.height()-.6f*scale)/2;float x=left+r.x*scale,y=top+r.y*scale,w=r.w*scale,h=r.h*scale;renderer_.rect(x,y,w,1,0xffffcc55);renderer_.rect(x,y+h-1,w,1,0xffffcc55);renderer_.rect(x,y,1,h,0xffffcc55);renderer_.rect(x+w-1,y,1,h,0xffffcc55);}}
    auto accept=screen.draw("AllianceAcceptButton",input.ui,{"AllianceAcceptButton"});auto cancel=screen.draw("AllianceCancelButton",input.ui,{"AllianceCancelButton"});if(input.ui.key==VK_ESCAPE || cancel=="AllianceCancelButton")return false;if(input.ui.key==VK_RETURN || accept=="AllianceAcceptButton"){
        std::int64_t gold=0,lumber=0;bool invalid=false;for(auto id:visible){int g=amount(allianceAmounts_[id][0]),l=amount(allianceAmounts_[id][1]);if((g || l) && !eligible(id))invalid=true;gold+=g;lumber+=l;}auto& states=session.config().players[local].states;auto balance=[&](unsigned key){auto it=states.find(key);return it==states.end()?0:it->second;};if(invalid)allianceError_="该玩家无法接收资源";else if(gold>balance(1) || lumber>balance(2))allianceError_="资源不足";else {bool failed=false;for(auto id:visible)for(unsigned bit:{0u,5u,6u}){auto mask=1u<<bit;if(!(allianceEdited_[id]&mask))continue;PlayerCommand alliance;alliance.player=local;alliance.kind=PlayerCommandKind::SetAlliance;alliance.otherPlayer=id;alliance.allianceOption=bit;alliance.enabled=(allianceOptions_[id]&mask)!=0;if(dispatchPlayerCommand(session,alliance))allianceEdited_[id]&=~mask;else failed=true;}if(!failed && allianceVictoryEdited_){PlayerCommand victory;victory.player=local;victory.kind=PlayerCommandKind::SetAlliedVictory;victory.enabled=allianceVictory_;if(dispatchPlayerCommand(session,victory))allianceVictoryEdited_=false;else failed=true;}if(failed)allianceError_="无法更改联盟设置";else {for(auto id:editable){int g=amount(allianceAmounts_[id][0]),l=amount(allianceAmounts_[id][1]);if(!g && !l)continue;PlayerCommand transfer;transfer.player=local;transfer.kind=PlayerCommandKind::TransferResources;transfer.otherPlayer=id;transfer.gold=g;transfer.lumber=l;if(dispatchPlayerCommand(session,transfer))allianceAmounts_[id]={};else failed=true;}if(!failed)return false;allianceError_="无法向该玩家转移资源";}}}
